import java.util.Scanner;

public class Main {
    static final int MAX = 1000007;
    static final long MOD = 1000000007L;
    static boolean[] visitedNodes = new boolean[MAX];
    static long[] divisorCounts = new long[MAX];
    static long[] cycleSizes = new long[MAX];
    static long[] dpArray = new long[MAX];

    static int getValue(Scanner sc) {
        return sc.nextInt();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long total = 1;
        int pVal = getValue(sc);
        int kVal = getValue(sc);

        for (int i = 0; i < pVal; i++) {
            if (!visitedNodes[i]) {
                int length = 0;
                long current = i;
                while (!visitedNodes[(int) current]) {
                    visitedNodes[(int) current] = true;
                    current = (kVal * current) % pVal;
                    length++;
                }
                cycleSizes[length]++;
            }
        }

        for (int i = 1; i <= pVal; i++) {
            dpArray[i] = (cycleSizes[i] * i) % MOD;
        }

        for (int i = 1; i <= pVal; i++) {
            divisorCounts[i] = (divisorCounts[i] + dpArray[i]) % MOD;
            for (int j = i + i; j <= pVal; j += i) {
                divisorCounts[j] = (divisorCounts[j] + dpArray[i]) % MOD;
            }
        }

        for (int i = 1; i <= pVal; i++) {
            if (i == 1) {
                for (int j = 0; j < cycleSizes[i] - 1; j++) {
                    total = (total * cycleSizes[i]) % MOD;
                }
            } else {
                for (int j = 0; j < cycleSizes[i]; j++) {
                    total = (total * divisorCounts[i]) % MOD;
                }
            }
        }

        if (kVal == 1) {
            total = (total * divisorCounts[1]) % MOD;
        }

        System.out.println(total);
        sc.close();
    }
}
